#include <bits/stdc++.h>
using namespace std;

class Solution {
public:
    string reformatDate(string date) {
        string dayToken, monthToken, yearToken;
        stringstream ss(date);
        ss >> dayToken >> monthToken >> yearToken;

        static const unordered_map<string, int> months = {
            {"Jan", 1}, {"Feb", 2}, {"Mar", 3}, {"Apr", 4},
            {"May", 5}, {"Jun", 6}, {"Jul", 7}, {"Aug", 8},
            {"Sep", 9}, {"Oct", 10}, {"Nov", 11}, {"Dec", 12}
        };

        int day = stoi(dayToken.substr(0, dayToken.size() - 2));
        int month = months.at(monthToken);
        int year = stoi(yearToken);

        ostringstream out;
        out << setw(4) << setfill('0') << year << '-'
            << setw(2) << setfill('0') << month << '-'
            << setw(2) << setfill('0') << day;
        return out.str();
    }
};

