    char day_token[6], month_token[4];
    int year;
    if (sscanf(date, "%5s %3s %d", day_token, month_token, &year) != 3) return NULL;

    day_token[strlen(day_token) - 2] = '\0';
    int day = atoi(day_token);
    int month = month_number(month_token);

    char *result = (char *)malloc(11);
    if (!result) return NULL;
    snprintf(result, 11, "%04d-%02d-%02d", year, month, day);
    return result;
}

